IF NOT(superState) THEN
    F_TempControlStatus := TempControlStatus.unknown;
ELSIF state = TempControlStates.idle THEN
    F_TempControlStatus := TempControlStatus.idle;
ELSIF state = TempControlStates.warming_up THEN
    F_TempControlStatus := TempControlStatus.warming_up;
ELSIF state = TempControlStates.controlling THEN
    F_TempControlStatus := TempControlStatus.controlling;
ELSE
    F_TempControlStatus := TempControlStatus.invalid_model;
END_IF;

model.isSimulated := THIS^.isSimulated;
