proc.initialize( isEnabled := NOT((stat.init = InitializationStatus.shutdown) OR ((stat.init = InitializationStatus.initializingFailed) OR ((stat.init = InitializationStatus.initialized) OR (stat.init = InitializationStatus.locked)))) );
proc.warm_up( isEnabled := (stat.state = TempControlStatus.idle) AND ((stat.init = InitializationStatus.initialized) AND (NOT(stat.init = InitializationStatus.locked))) );
proc.stop( isEnabled := (stat.state = TempControlStatus.warming_up) OR (stat.state = TempControlStatus.controlling) );
proc.reset( isEnabled := NOT(stat.init = InitializationStatus.locked) );
proc.lock( isEnabled := (operator_ref = OperatorStatus.tech) AND (stat.init = InitializationStatus.locked) );
proc.unlock( isEnabled := (operator_ref = OperatorStatus.tech) AND (stat.init = InitializationStatus.locked) );

